param()

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
[Console]::InputEncoding = [System.Text.UTF8Encoding]::new()
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new()
$OutputEncoding = [System.Text.UTF8Encoding]::new()

if ($env:OS -ne 'Windows_NT') { throw 'The WPF build requires Windows and Visual Studio MSBuild.' }
$projectRoot = Split-Path $PSScriptRoot -Parent
Push-Location $projectRoot
try {
    $output = Join-Path $projectRoot 'NEW_CLEVER/bin/PackageRelease'
    # This isolated output is generated by this script, never a user project directory.
    if (Test-Path $output) { Remove-Item -LiteralPath $output -Recurse -Force }
    & msbuild 'NEW_CLEVER/NEW_CLEVER.csproj' /restore /t:Build /m /v:minimal `
        /p:Configuration=Release /p:Platform=AnyCPU /p:RestorePackagesConfig=true "/p:SolutionDir=$projectRoot/" `
        /p:OutputPath='bin\PackageRelease\'
    if ($LASTEXITCODE -ne 0) { throw 'NEW_CLEVER build failed.' }

    $bridgeOutput = Join-Path $projectRoot 'NEW_CLEVER.AgentMcpBridge/bin/PackageRelease'
    if (!(Test-Path $bridgeOutput)) { throw 'MCP bridge build output is missing.' }
    Copy-Item -Path (Join-Path $bridgeOutput '*') -Destination $output -Recurse -Force
    Copy-Item -Path 'NEW_CLEVER/RuntimeData/*' -Destination $output -Recurse -Force
    Copy-Item -LiteralPath 'NEW_CLEVER/NEW_CLEVERIcon.ico' -Destination $output -Force
    Copy-Item -LiteralPath 'README.md' -Destination $output -Force

    foreach ($required in @('NEW_CLEVER.exe', 'NEW_CLEVER Registry.exe', 'Interpreter.dll',
            'NEW_CLEVER.AgentCore.dll', 'NEW_CLEVER.AgentMcpBridge.exe', 'Localization/en/interface_en.txt')) {
        if (!(Test-Path (Join-Path $output $required))) { throw "Required package file is missing: $required" }
    }
    $metadata = [System.Diagnostics.FileVersionInfo]::GetVersionInfo((Join-Path $output 'NEW_CLEVER.exe'))
    if ($metadata.ProductName -ne 'NEW_CLEVER') { throw 'Executable product metadata does not match NEW_CLEVER.' }
    $staleExecutables = Get-ChildItem -LiteralPath $output -Recurse -File |
        Where-Object { $_.Name -match '^(Clever|Clev3r)([. ]|$)' }
    if ($staleExecutables) { throw 'The package contains legacy product outputs.' }

    $artifactDirectory = Join-Path $projectRoot 'artifacts'
    New-Item -ItemType Directory -Force -Path $artifactDirectory | Out-Null
    $archive = Join-Path $artifactDirectory 'NEW_CLEVER-1.8.0-Windows-x64.zip'
    Compress-Archive -Path (Join-Path $output '*') -DestinationPath $archive -Force
    Get-FileHash -LiteralPath $archive -Algorithm SHA256
}
finally {
    Pop-Location
}
